35	export async function modeSetup(record: SessionRecord, ctx: ModeContext): Promise<ModeSetup> {
36	  const { workspaceRoot } = ctx
37	  // A chat may write a spec when asked to, held to the contract like the planner's.
38	  const chat = { hooks: new SpecContract(workspaceRoot) }
39	  if (record.access === 'full') return chat
40	  switch (record.mode) {
41	    case 'chat':
42	      return chat
43	    case 'implement': {
44	      if (!record.feature) throw new Error('An implement session needs a feature name')
45	      return {
46	        // The user's answers amend the task's rules, held to the contract like the planner's writes.
47	        hooks: composeHooks(new TaskBoardGuard(workspaceRoot, record.feature), new SpecContract(workspaceRoot)),
48	        systemPrompt: await ctx.withMemories(record, await ctx.withMap(record, implementPrompt(record.feature, workspaceRoot, ctx.verifyRules()))),
49	        toolNames: IMPLEMENT_TOOLS,
50	      }
51	    }
52	    case 'plan': {
53	      if (!record.feature) throw new Error('A plan session needs a feature name')
54	      const scope = blindPlanScope(record.feature, ctx.planIgnore())
55	      return {
56	        // The contract answers on the write that broke it, so the planner fixes the spec in the same turn.
57	        hooks: composeHooks(new ScopeGuard(workspaceRoot, scope), new SpecContract(workspaceRoot)),
58	        systemPrompt: await ctx.withDocs(record, blindPlanPrompt(record.feature, workspaceRoot)),
59	        toolNames: BLIND_PLAN_TOOLS,
60	        readable: readableIn(scope),
61	      }
62	    }
63	    case 'code-plan':
64	      // Read-only by its tool set: nothing to scope, and the build happens once the plan is approved.
65	      return {
66	        systemPrompt: await ctx.withMemories(record, await ctx.withMap(record, await ctx.withDocs(record, codePlanPrompt(workspaceRoot)))),
67	        toolNames: CODE_PLAN_TOOLS,
68	      }
69	    case 'docs': {
70	      const scope = docsEvaluationScope(ctx.planIgnore())
71	      return {
72	        hooks: new ScopeGuard(workspaceRoot, scope),
73	        systemPrompt: await ctx.withMemories(record, await ctx.withDocs(record, docsEvaluationPrompt(workspaceRoot))),
74	        toolNames: DOCS_EVALUATION_TOOLS,
75	        readable: readableIn(scope),
76	      }
77	    }
78	    case 'file-decisions': {
79	      const scope = fileDecisionsScope(ctx.planIgnore())
