92	        toolNames: DOCS_MAP_TOOLS,
93	      }
94	    }
95	    case 'reconcile': {
96	      if (!record.feature) throw new Error('A reconcile session needs a feature name')
97	      return {
98	        hooks: composeHooks(
99	          new ScopeGuard(workspaceRoot, reconcileScope(record.feature)),
100	          new SpecContract(workspaceRoot),
101	          new ScenarioContextContract(workspaceRoot, record.feature),
102	        ),
103	        systemPrompt: await ctx.withMemories(record, await ctx.withMap(record, reconcilePrompt(record.feature, workspaceRoot))),
104	        toolNames: RECONCILE_TOOLS,
