3	/** `implemented` is written by the extension once the feature is verified, so the stage outlives the working files. */
4	export type SpecStatus = 'draft' | 'approved' | 'implemented'
5	
6	/** `body` is the markdown after the front matter, what a reader should see. */
7	export type SpecState = { exists: false } | { exists: true; status: SpecStatus; body: string }
8	
9	export const FRONT_MATTER = /^---\r?\n([\s\S]*?)\r?\n---(\r?\n|$)/
10	
11	/** The value of one front-matter line, `key: value`; undefined without front matter or the key. */
12	export function frontMatterValue(text: string, key: string): string | undefined {
13	  const match = FRONT_MATTER.exec(text)
14	  const line = match?.[1]?.split(/\r?\n/).find((l) => l.startsWith(`${key}:`))
15	  const value = line?.slice(key.length + 1).trim()
16	  return value || undefined
17	}
18	
19	/** Sets one front-matter line, adding the front matter when the text has none. */
20	export function withFrontMatterValue(text: string, key: string, value: string): string {
21	  const match = FRONT_MATTER.exec(text)
22	  if (!match) return `---\n${key}: ${value}\n---\n\n${text}`
23	  const lines = match[1]!.split(/\r?\n/)
24	  const index = lines.findIndex((l) => l.startsWith(`${key}:`))
25	  if (index === -1) lines.push(`${key}: ${value}`)
26	  else lines[index] = `${key}: ${value}`
27	  return text.replace(FRONT_MATTER, `---\n${lines.join('\n')}\n---${match[2]}`)
28	}
