30	/**
31	 * The spec's front-matter `status` is the approval gate: phase 2 refuses a
32	 * draft, and a human sets `approved`. Held in the file so it survives
33	 * reloads and is visible in git.
34	 */
35	export async function readSpecState(path: string): Promise<SpecState> {
36	  let text: string
37	  try {
38	    text = await readFile(path, 'utf8')
39	  } catch (error) {
40	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return { exists: false }
41	    throw error
42	  }
43	  return { exists: true, status: statusOf(text), body: bodyOf(text) }
44	}
45	
46	export function bodyOf(text: string): string {
47	  return text.replace(FRONT_MATTER, '').replace(/^\s+/, '')
48	}
49	
50	export function statusOf(text: string): SpecStatus {
51	  const value = frontMatterValue(text, 'status')
52	  return value === 'approved' || value === 'implemented' ? value : 'draft'
53	}
